#[test]
fn status_lists_context_and_all_manifest_repos() {
    let fixture = synced_fixture();

    let out = stdout_of(&fixture.run(&["status"]));
    assert!(
        out.contains(&format!("WORKSPACE {}", fixture.workspace.display())),
        "no workspace line: {out}"
    );
    assert!(out.contains("REPOSITORY"), "no table header: {out}");
    for name in [CONTEXT, REPOS[0], REPOS[1]] {
        assert!(out.contains(name), "{name} missing from: {out}");
    }
    // Freshly cloned checkouts are clean and level with their origins.
    assert_eq!(out.matches("clean").count(), 3, "{out}");
    assert_eq!(out.matches("current").count(), 5, "{out}");
}

#[test]
fn status_reports_modified_for_dirty_repo() {
    let fixture = synced_fixture();
    fixture.write("zl-zpr-core/README.md", "locally edited\n");

    let out = stdout_of(&fixture.run(&["status"]));
    assert!(out.contains("modified"), "{out}");
    assert_eq!(out.matches("clean").count(), 2, "{out}");
}

#[test]
fn status_reports_behind_after_origin_advances_and_fetch() {
    let fixture = synced_fixture();

    // Before the fetch there is nothing local to compare against, so `status`
    // still reports `current` — it performs no network access itself.
    fixture.commit_to_origin("zl-zpr-core");
    assert!(!stdout_of(&fixture.run(&["status"])).contains("behind"));

    common::git(&fixture.workspace.join("zl-zpr-core"), &["fetch"]);
    let out = stdout_of(&fixture.run(&["status"]));
    assert!(out.contains("behind 1"), "{out}");
}

#[test]
fn status_reports_missing_repository_when_not_cloned() {
    let fixture = Fixture::new();

    let out = stdout_of(&fixture.run(&["status"]));
    assert_eq!(out.matches("missing repository").count(), 2, "{out}");
    // The table reports the absent checkouts too, with no branch or upstream.
    assert_eq!(out.matches("missing").count(), 4, "{out}");
    assert_eq!(out.matches("no upstream").count(), 2, "{out}");
}

#[test]
fn status_agent_context_is_stale_before_sync_and_current_after() {
    let fixture = Fixture::new();
    fixture.clone_repos();

    let out = stdout_of(&fixture.run(&["status"]));
    assert_eq!(out.matches("stale").count(), 2, "{out}");

    stdout_of(&fixture.run(&["sync"]));
    let out = stdout_of(&fixture.run(&["status"]));
    assert!(!out.contains("stale"), "{out}");

    // A hand-edited generated file is stale again.
    fixture.write(
        "zl-zpr-core/AGENTS.md",
        &format!("{GENERATED_MARKER}\nclobbered\n"),
    );
    let out = stdout_of(&fixture.run(&["status"]));
    assert_eq!(out.matches("stale").count(), 1, "{out}");
}

/// A file with no marker is not ours, so it is reported as such rather than as
/// drift `sync` could clear.
#[test]
fn status_reports_a_file_zpr_dev_did_not_generate() {
    let fixture = synced_fixture();
    fixture.write("zl-zpr-core/AGENTS.md", "our own conventions\n");

    let out = stdout_of(&fixture.run(&["status"]));
    assert!(out.contains("not generated by zpr-dev"), "{out}");
    assert!(!out.contains("stale"), "{out}");
}

#[test]
fn status_porcelain_field_order_is_stable() {
    let fixture = synced_fixture();

    let out = stdout_of(&fixture.run(&["status", "--porcelain"]));
    let lines: Vec<_> = out.lines().collect();
    assert_eq!(
        lines,
        vec![
            "repo\tzl-zpr-dev-context\tmain\tclean\t0\t0",
            "repo\tzl-zpr-core\tmain\tclean\t0\t0",
            "repo\tzl-zpr-common\tmain\tclean\t0\t0",
            "agent\tzl-zpr-core\tcurrent",
            "agent\tzl-zpr-common\tcurrent",
        ],
        "porcelain output changed shape"
    );
}

#[test]
fn status_repo_flag_restricts_output() {
    let fixture = synced_fixture();

    let out = stdout_of(&fixture.run(&["status", "--porcelain", "--repo", "zl-zpr-core"]));
    assert_eq!(
        out.lines().collect::<Vec<_>>(),
        vec![
            "repo\tzl-zpr-core\tmain\tclean\t0\t0",
            "agent\tzl-zpr-core\tcurrent"
        ]
    );

    // The context checkout is a legitimate target, with no generated context.
    let out = stdout_of(&fixture.run(&["status", "--porcelain", "--repo", CONTEXT]));
    assert_eq!(
        out.lines().collect::<Vec<_>>(),
        vec!["repo\tzl-zpr-dev-context\tmain\tclean\t0\t0"]
    );

    // An unknown name is a command error, not empty output.
    let output = fixture.run(&["status", "--repo", "nope"]);
    assert_eq!(output.status.code(), Some(2));
    assert!(String::from_utf8_lossy(&output.stderr).contains("unknown repository"));
}

/// Asserts the exit code, and returns stdout — `validate` reports its findings
/// on stdout whether it passes or fails.
fn output_with_code(output: &std::process::Output, code: i32) -> String {
    assert_eq!(
        output.status.code(),
        Some(code),
        "unexpected exit code; stdout: {}\nstderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8_lossy(&output.stdout).to_string()
}

#[test]
fn validate_healthy_workspace_exits_zero() {
    let fixture = synced_fixture();

    let out = output_with_code(&fixture.run(&["validate"]), 0);
    assert!(!out.contains("[ERROR]"), "{out}");
    assert!(!out.contains("[WARN]"), "{out}");
    for check in [
        "context repository",
        "workspace manifest",
        "2 source repositories",
        "generated context",
        "documentation references",
    ] {
        assert!(out.contains(check), "{check} not reported: {out}");
    }
    assert!(
        out.contains("Validation completed with 0 warnings."),
        "{out}"
    );
}

#[test]
fn validate_broken_doc_reference_exits_one() {
    let fixture = synced_fixture();
    let agents = fixture.read(&format!("{CONTEXT}/AGENTS.md"));
    fixture.write(
        &format!("{CONTEXT}/AGENTS.md"),
        &format!("{agents}\nSee [the missing one](docs/GONE.md) too.\n"),
    );

    let out = output_with_code(&fixture.run(&["validate"]), 1);
    assert!(
        out.contains("[ERROR] documentation reference does not resolve: docs/GONE.md"),
        "{out}"
    );
    // The reference that does resolve is not reported.
    assert!(!out.contains("docs/EXAMPLE.md"), "{out}");
}

/// A document nothing indexes warns but does not fail: it is documentation
/// drift, not a broken workspace.
#[test]
fn validate_orphaned_doc_warns_and_exits_zero() {
    let fixture = synced_fixture();
    fixture.write("zl-zpr-dev-context/docs/ORPHAN.md", "# Nobody links me\n");

    let out = output_with_code(&fixture.run(&["validate"]), 0);
    assert!(
        out.contains("[WARN] no index references docs/ORPHAN.md"),
        "{out}"
    );
    // The indexed document is not reported.
    assert!(!out.contains("docs/EXAMPLE.md"), "{out}");
    assert!(
        out.contains("Validation completed with 1 warning."),
        "{out}"
    );
}

/// Linking the document from the shared context clears the warning, which is
/// the fix the message tells the reader to apply.
#[test]
fn validate_indexed_doc_reports_ok() {
    let fixture = synced_fixture();
    fixture.write("zl-zpr-dev-context/docs/ORPHAN.md", "# Now linked\n");
    let agents = fixture.read(&format!("{CONTEXT}/AGENTS.md"));
    fixture.write(
        &format!("{CONTEXT}/AGENTS.md"),
        &format!("{agents}\nSee [the new one](docs/ORPHAN.md).\n"),
    );

    let out = output_with_code(&fixture.run(&["validate"]), 0);
    assert!(out.contains("documentation is indexed"), "{out}");
    // Editing the shared context makes the generated files stale, which is a
    // separate and expected warning; what must be absent is the orphan one.
    assert!(!out.contains("no index references"), "{out}");
}

