/// The `zl-zpr-visaservice` regression, end to end: a repository that keeps its own
/// `AGENTS.md` must get an error a human has to act on, and `sync` must leave
/// the file's contents alone.
#[test]
fn foreign_agents_file_errors_in_validate_and_survives_sync() {
    let fixture = synced_fixture();
    let hand_written = "# AGENTS.md\n\nNever patch a failing test you didn't write.\n";
    fixture.write("zl-zpr-core/AGENTS.md", hand_written);

    let out = output_with_code(&fixture.run(&["validate"]), 1);
    assert!(
        out.contains("[ERROR] zl-zpr-core:") && out.contains("was not generated by zpr-dev"),
        "{out}"
    );
    assert!(out.contains("rename it to AGENTS.repo.md"), "{out}");

    let out = stdout_of(&fixture.run(&["sync"]));
    assert!(out.contains("refusing to overwrite"), "{out}");
    assert_eq!(
        fixture.read("zl-zpr-core/AGENTS.md"),
        hand_written,
        "sync must not overwrite a file it did not generate"
    );
}

/// The escape hatch for a workspace that has decided the shared context wins:
/// `--force` warns instead of erroring, `validate` passes, and `sync` clobbers.
#[test]
fn force_downgrades_foreign_to_a_warning_and_overwrites() {
    let fixture = synced_fixture();
    fixture.write(
        "zl-zpr-core/AGENTS.md",
        "# AGENTS.md\n\nNever patch a failing test you didn't write.\n",
    );

    let out = stdout_of(&fixture.run(&["--force", "validate"]));
    assert!(
        out.contains("[WARN]") && out.contains("--force will overwrite it"),
        "{out}"
    );

    let out = stdout_of(&fixture.run(&["--force", "sync"]));
    assert!(out.contains("overwriting"), "{out}");
    assert!(
        fixture
            .read("zl-zpr-core/AGENTS.md")
            .starts_with(GENERATED_MARKER),
        "sync --force must replace the hand-written file"
    );
}

#[test]
fn validate_bad_manifest_version_exits_one() {
    let fixture = synced_fixture();
    let manifest = fixture.read(&format!("{CONTEXT}/workspace.yaml"));
    fixture.write(
        &format!("{CONTEXT}/workspace.yaml"),
        &manifest.replace("version: 1", "version: 2"),
    );

    let out = output_with_code(&fixture.run(&["validate"]), 1);
    assert!(out.contains("[ERROR] workspace manifest"), "{out}");
    // The manifest is the gate for every later check, so nothing follows it.
    assert!(!out.contains("source repositories"), "{out}");
}

#[test]
fn validate_missing_shared_skills_dir_warns_and_exits_zero() {
    let fixture = synced_fixture();
    // The fixture manifest has no `agent` block, so the declaration is added
    // here. `validate` reads the file from disk; no commit is needed.
    let manifest = fixture.read(&format!("{CONTEXT}/workspace.yaml"));
    fixture.write(
        &format!("{CONTEXT}/workspace.yaml"),
        &format!("{manifest}agent:\n  hermes:\n    shared_skills: skills\n"),
    );

    let out = output_with_code(&fixture.run(&["validate"]), 0);
    assert!(
        out.contains("[WARN] shared skills directory missing"),
        "{out}"
    );
    assert!(
        out.contains("Validation completed with 1 warning."),
        "{out}"
    );

    // Present is an [OK] line, and the workspace is clean again.
    fixture.write(&format!("{CONTEXT}/skills/EXAMPLE.md"), "a skill\n");
    let out = output_with_code(&fixture.run(&["validate"]), 0);
    assert!(out.contains("[OK]   shared skills skills"), "{out}");
}

