#[test]
fn update_repo_flag_targets_one_repository() {
    let fixture = behind_fixture();
    let targeted = short_head(&fixture, REPOS[0]);
    let other = short_head(&fixture, REPOS[1]);
    let context = short_head(&fixture, CONTEXT);

    let out = stdout_of(&fixture.run(&["update", "--repo", REPOS[0]]));

    assert_ne!(short_head(&fixture, REPOS[0]), targeted, "{out}");
    assert_eq!(short_head(&fixture, REPOS[1]), other);
    assert_eq!(short_head(&fixture, CONTEXT), context);
    assert!(!out.contains(REPOS[1]), "untargeted repository: {out}");

    // An unknown name is an error, not empty output, as in `status`.
    let unknown = fixture.run(&["update", "--repo", "no-such-repo"]);
    assert_eq!(unknown.status.code(), Some(2));
}

#[test]
fn update_no_generate_skips_regeneration() {
    let fixture = synced_fixture();
    // A new repository-specific context file makes the generated file stale.
    fixture.write(
        &format!("{}/AGENTS.repo.md", REPOS[0]),
        "Repository rules.\n",
    );

    let out = stdout_of(&fixture.run(&["update", "--all", "--no-generate"]));
    assert!(!out.contains("generated context"), "regenerated: {out}");
    assert!(
        !fixture
            .read(&format!("{}/AGENTS.md", REPOS[0]))
            .contains("Repository rules."),
        "generated file was rewritten"
    );

    // Without the flag, the same run regenerates it.
    let out = stdout_of(&fixture.run(&["update", "--all"]));
    assert!(out.contains("1 updated"), "{out}");
    assert!(
        fixture
            .read(&format!("{}/AGENTS.md", REPOS[0]))
            .contains("Repository rules.")
    );
}

#[test]
fn dry_run_update_does_not_move_head() {
    let fixture = behind_fixture();
    fixture.commit_to_origin(CONTEXT);
    let before: Vec<String> = [CONTEXT, REPOS[0], REPOS[1]]
        .iter()
        .map(|name| short_head(&fixture, name))
        .collect();

    let out = stdout_of(&fixture.run(&["update", "--all", "--dry-run"]));

    assert!(out.contains("would fetch and fast-forward"), "{out}");
    for (name, sha) in [CONTEXT, REPOS[0], REPOS[1]].iter().zip(&before) {
        assert_eq!(&short_head(&fixture, name), sha, "{name} moved");
    }
}

